    private static DocumentBlock Node(string name, Formula statement, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("paircurvatureinequality-" + name.Replace('.', '-').Replace('_', '-').ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(name),
            StatementSource.FromAuthor(statement), name == "newton2" || name == "newton3" || name == "newton4" || name == "E_one_eq_sum"
